    /// A week on battery, charged once: whole-percent readings at the wakes.
    private static func demoReadings() -> [BatteryReading] {
        let formatter = ISO8601DateFormatter()
        let levels = [96, 92, 89, 100, 100, 97, 94, 91, 88, 85, 82, 79, 76]
        return levels.enumerated().map { index, level in
            let at = Date.now.addingTimeInterval(Double(index - levels.count + 1) * 12 * 3600 - 3600)
            return BatteryReading(at: formatter.string(from: at), level: level)
        }
    }

    func player() async throws -> PlayerView {
        let current = currentID.flatMap { id in items.first { $0.id == id } }
        let playlist = settingsValue.playlistId.flatMap { playlistsByID[$0] }.map(summary)
        let nowShowing = current.map {
            NowShowing(
                title: $0.title, description: "\($0.artist) — \($0.title)", source: $0.source,
                created: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-5400)),
                previewUrl: "/demo/\($0.id)?\(shared.shown.presentationKey)|\(framingRevision)", item: $0
            )
        }
        let next = settingsValue.changeTimes.compactMap { time -> Date? in
            let parts = time.split(separator: ":").compactMap { Int($0) }
            guard parts.count == 2 else { return nil }
            return Calendar.current.nextDate(
                after: .now, matching: DateComponents(hour: parts[0], minute: parts[1]), matchingPolicy: .nextTime
            )
        }.min()
        return PlayerView(
            playlist: playlist, current: nowShowing,
            upcoming: queue.prefix(8).compactMap { id in items.first { $0.id == id }?.summary },
            queued: queued,
            history: history.suffix(8).reversed().compactMap { id in items.first { $0.id == id }?.summary },
            hold: holdValue,
            lastChangeAt: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-5400)),
            nextChangeAt: next.map { ISO8601DateFormatter().string(from: $0) },
            busy: runElapsed.map { $0 < 5 } ?? false, lastError: nil, progress: try await progress(),
            historyMarks: demoMarks()
        )
    }

    /// Who put the pictures of "Ostatnio na ramce" there: the schedule at
    /// 7:00 and 19:30, and one sent from the app in between.
    private func demoMarks() -> [String: ShownMark] {
        let ids = Array(history.suffix(8).reversed())
        var marks: [String: ShownMark] = [:]
        for (index, id) in ids.enumerated() {
            let fromApp = index % 3 == 1
            let hours = 5400.0 / 3600 + Double(index) * 6 + (fromApp ? 3 : 0)
            marks[id] = ShownMark(
                at: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-hours * 3600)),
                origin: fromApp ? "app" : "schedule"
            )
        }
        return marks
    }

    private var runElapsed: Double? {
        guard let run else { return nil }
        let elapsed = Date.now.timeIntervalSince(run.start)
        // CI screenshots: `-drawn 0.4` stops the drawing at that share, so a
        // capture finds it there whenever the app came up.
        guard let drawn = LaunchRoute.drawn, let drawing = Self.runStages.last else { return elapsed }
        let total = Self.runStages.reduce(0) { $0 + $1.seconds }
        return min(elapsed, total - drawing.seconds * (1 - drawn))
    }

    /// A picture on its way to the frame: drawn with the settings as they are now.
    private func startRun(_ title: String, itemID: String? = nil) {
        run = (title: title, itemID: itemID, start: Date.now)
        shared.shown = settingsValue
    }

    private func startRun(itemID: String?) {
        startRun(items.first { $0.id == itemID }?.title ?? "", itemID: itemID)
    }

    func progress() async throws -> DisplayProgress {
        guard let run, let elapsed = runElapsed else { return .idle }
        let stamp = ISO8601DateFormatter().string(from: run.start)
        let total = Self.runStages.reduce(0) { $0 + $1.seconds }
        var end = 0.0
        for step in Self.runStages {
            end += step.seconds
            if elapsed < end {
                // The phase's own share: its stages from the first to the last.
                let before = Self.runStages.prefix { $0.phase != step.phase }.reduce(0) { $0 + $1.seconds }
                let length = Self.runStages.filter { $0.phase == step.phase }.reduce(0) { $0 + $1.seconds }
                return DisplayProgress(
                    stage: step.stage, phase: step.phase, active: true, title: run.title,
                    fraction: elapsed / total, phaseFraction: (elapsed - before) / length,
                    secondsLeft: Int((total - elapsed).rounded(.up)),
                    startedAt: stamp, origin: "app", itemId: run.itemID
                )
            }
        }
        return DisplayProgress(
            stage: "done", active: false, title: run.title, fraction: 1, startedAt: stamp,
            finishedAt: ISO8601DateFormatter().string(from: run.start.addingTimeInterval(total))
        )
    }

    func next() async throws {
        guard !queue.isEmpty else { return }
        if let currentID { history.append(currentID) }
        currentID = queue.removeFirst()
        queued.removeAll { $0 == currentID }
        holdValue = nil
        startRun(itemID: currentID)
    }

    func previous() async throws {
        guard let previous = history.popLast() else { return }
        if let currentID { queue.insert(currentID, at: 0) }
        currentID = previous
        holdValue = nil
        startRun(itemID: currentID)
    }

    func hold(_ spec: HoldSpec) async throws -> PlayerView {
        switch spec {
        case .untilNextChange: holdValue = nil
        case .forever: holdValue = Hold(until: nil, forever: true)
        default:
            let minutes = Double(spec.wireValue) ?? 60
            holdValue = Hold(
                until: ISO8601DateFormatter().string(from: .now.addingTimeInterval(minutes * 60)),
                forever: false
            )
        }
        return try await player()
    }

    func releaseHold() async throws -> PlayerView {
        holdValue = nil
        return try await player()
    }

