    func daily(day: String?, wait: Int, lists: Bool) async throws -> DailyWork {
        func found(_ id: String) -> Item? { items.first { $0.id == id } }
        guard let wave = found("aic:24645") ?? items.max(by: { ($0.suitability ?? 0) < ($1.suitability ?? 0) }) else {
            throw BackendError.notFound
        }
        let today = Calendar.current.startOfDay(for: Date())
        func iso(_ daysAgo: Int) -> String {
            let date = Calendar.current.date(byAdding: .day, value: -daysAgo, to: today) ?? today
            let parts = Calendar.current.dateComponents([.year, .month, .day], from: date)
            return String(format: "%04d-%02d-%02d", parts.year ?? 0, parts.month ?? 0, parts.day ?? 0)
        }
        let similar: [DailyWork.Similar] = [
            ("aic:87008", "ta sama seria"), ("aic:2914", "drzeworyt, ten sam czas"),
            ("aic:14620", "morze widziane z góry"),
        ].compactMap { id, why in
            found(id).map { DailyWork.Similar(item: RemoteItem(item: $0, inLibrary: true), why: why) }
        }
        let cuts: [(String, String, Double, Double, Double, Double)] = [
            ("Pazury piany", "Grzbiet fali rozpada się w drobne, zakrzywione palce piany, zawieszone nad łodziami tuż przed uderzeniem.", 0.415, 0.12, 0.2, 0.3),
            ("Wioślarze", "Ośmiu wioślarzy wtulonych w burtę łodzi. Twarze to kilka kresek, a cała łódź jest ledwie dłuższa niż grzbiet fali.", 0.6, 0.74, 0.24, 0.24),
            ("Tytuł i sygnatura", "W prostokątnym kartuszu tytuł serii i obrazu; obok podpis: „z pędzla Hokusaia, zmienione imię Iitsu”.", 0.012, 0.06, 0.115, 0.29),
        ]
        typealias Spot = DailyWork.Spot
        var work = DailyWork(
            day: day ?? iso(0),
            item: RemoteItem(item: wave, inLibrary: true),
            title: "Wielka fala w Kanagawie",
