    func study(itemID: String, wait: Int, lists: Bool) async throws -> StudyView {
        guard let asked = askedStudies[itemID] else {
            let status = laterStudies.contains(itemID) ? "later" : "none"
            return StudyView(status: status, error: "", work: nil, costUsd: 0.14, laterCostUsd: 0.07)
        }
        let elapsed = Date().timeIntervalSince(asked)
        if elapsed < 6 {
            try? await Task.sleep(for: .seconds(min(Double(wait), 2)))
            return StudyView(status: elapsed < 2 ? "sources" : "writing", error: "", work: nil, costUsd: 0.14)
        }
        guard let item = items.first(where: { $0.id == itemID }) else { throw BackendError.notFound }
        var work = try await daily(day: nil, wait: 0)
        work.day = ""
        work.whyToday = ""
        if work.item.id != itemID {
            // The demo's text is about the wave: another work keeps what its museum says.
            work.item = RemoteItem(item: item, inLibrary: true)
            work.title = item.title
            work.teaser = ""
            work.headline = "Co mówi muzeum"
            work.context = item.description.isEmpty ? [] : [item.description]
            work.artist = item.artistBio
            work.composition = nil
            work.colour = ""
            work.details = []
            work.onFrame = ""
            work.legacy = []
            work.similar = []
            work.byArtist = byArtist(item, skip: [])
        }
        if !lists {
            work.similar = []
            work.legacy = []
            work.byArtist = []
            work.sameTime = []
            work.partial = true
        }
        return StudyView(status: "ready", error: "", work: work, costUsd: 0.14)
    }

    /// Up to six other works by `item`'s artist ("Inne prace artysty").
    private func byArtist(_ item: Item, skip: Set<String>) -> [RemoteItem] {
        guard !item.artist.isEmpty else { return [] }
        return items
            .filter { $0.id != item.id && !skip.contains($0.id) && $0.artist == item.artist }
            .prefix(6)
            .map { RemoteItem(item: $0, inLibrary: true) }
    }

    /// The ones asked for (the last first), then a few the demo has written;
    /// the wave is today's work of the day and opens as that.
    func studies() async throws -> [StudyBrief] {
        let asked = askedStudies.filter { Date().timeIntervalSince($0.value) >= 6 }.sorted { $0.value > $1.value }.map { $0.key }
        let ids = asked + ["aic:24645", "aic:14620", "aic:64818", "aic:87008", "aic:2914"].filter { !asked.contains($0) }
        let parts = Calendar.current.dateComponents([.year, .month, .day], from: Date())
        let today = String(format: "%04d-%02d-%02d", parts.year ?? 0, parts.month ?? 0, parts.day ?? 0)
        return ids.compactMap { id in
            items.first { $0.id == id }.map {
                StudyBrief(
                    item: RemoteItem(item: $0, inLibrary: true),
                    title: $0.title,
                    day: id == "aic:24645" && !asked.contains(id) ? today : nil
                )
            }
        }
    }

    func prepareStudy(itemID: String, again: Bool, later: Bool) async throws -> StudyView {
        if later, !again {
            if askedStudies[itemID] == nil { laterStudies.insert(itemID) }
            return try await study(itemID: itemID, wait: 0, lists: true)
        }
        laterStudies.remove(itemID)
        if again || askedStudies[itemID] == nil { askedStudies[itemID] = Date() }
        return try await study(itemID: itemID, wait: 0, lists: true)
    }

    /// The analysis on its way, made once its time has come.
    private func settleAnalysis(_ itemID: String) {
        guard var kept = analyses[itemID], let ready = kept.readyAt, ready <= Date() else { return }
        kept.made.append(ISO8601DateFormatter().string(from: ready))
        kept.shown = kept.made.count - 1
        kept.readyAt = nil
        analyses[itemID] = kept
    }

    private func analysisState(_ itemID: String) -> CompositionAgain {
        settleAnalysis(itemID)
        let kept = analyses[itemID]
        return CompositionAgain(pending: kept?.readyAt != nil, versions: kept?.made.count ?? 0)
    }

    /// The demo's analysis "made" anew a few seconds later (the same one).
    func compositionAgain(itemID: String) async throws -> CompositionAgain {
        var kept = analyses[itemID] ?? (
            made: [ISO8601DateFormatter().string(from: .now.addingTimeInterval(-86400))], shown: 0, readyAt: nil
        )
        kept.readyAt = .now.addingTimeInterval(8)
        analyses[itemID] = kept
        return analysisState(itemID)
    }

    func compositionState(itemID: String) async throws -> CompositionAgain { analysisState(itemID) }

    func pickComposition(itemID: String, shown: Int) async throws -> CompositionAgain {
        guard var kept = analyses[itemID], kept.made.indices.contains(shown) else { throw BackendError.notFound }
        kept.shown = shown
        analyses[itemID] = kept
        return analysisState(itemID)
    }

    /// The demo's check "done" a few seconds later, every box where it was.
    func detailsAgain(itemID: String) async throws -> DetailsAgain {
        detailChecks[itemID] = .now.addingTimeInterval(6)
        return try await detailsState(itemID: itemID)
    }

    func detailsState(itemID: String) async throws -> DetailsAgain {
        let pending = (detailChecks[itemID] ?? .distantPast) > Date()
        return DetailsAgain(pending: pending, moved: pending ? nil : [])
    }

