    func themePlaylist(key: String, play: Bool) async throws -> ThemePlaylist {
        guard let theme = DemoDiscover.themes.first(where: { $0.key == key }) else {
            throw BackendError.notFound
        }
        let id: Int
        if let existing = themePlaylistID(theme) {
            id = existing
        } else {
            let made = try await savePlaylist(
                Playlist(
                    name: theme.name, description: theme.description, kind: .smart,
                    rules: theme.rules ?? PlaylistRules(), theme: theme.key
                )
            )
            id = made.playlist.id
        }
        if play { try await self.play(playlistID: id) }
        guard let playlist = playlistsByID[id] else { throw BackendError.notFound }
        return ThemePlaylist(playlist: summary(playlist), jobId: nil)
    }

    func vocabulary() async throws -> [TermInfo] { DemoDiscover.terms }

    func terms(_ text: String) async throws -> [TermHit] {
        let wanted = DemoDiscover.fold(text.trimmingCharacters(in: .whitespaces))
        guard !wanted.isEmpty else { return [] }
        var hits: [TermHit] = []
        let artists = Dictionary(grouping: items.filter { DemoDiscover.fold($0.artist).contains(wanted) }, by: \.artist)
        hits += artists.map { TermHit(kind: "artist", key: $0.key, name: $0.key, count: $0.value.count) }
            .sorted { $0.count > $1.count }
        for term in DemoDiscover.terms {
            let names = [term.name] + term.words
            guard names.contains(where: { DemoDiscover.fold($0).hasPrefix(wanted) }) else { continue }
            let count = items.filter { Self.matches($0, PlaylistRules(terms: [term.key])) }.count
            hits.append(
                TermHit(
                    kind: term.kind, key: term.key, name: term.name,
                    detail: term.words.prefix(3).joined(separator: ", "), count: count
                )
            )
        }
        let words = text.trimmingCharacters(in: .whitespaces)
        let count = items.filter { Self.matches($0, PlaylistRules(query: words)) }.count
        hits.append(TermHit(kind: "word", key: words, name: words, count: count))
        return hits
    }

    func looksStatus() async throws -> LooksStatus {
        let works = items.filter { $0.kind == .artwork }.count
        return LooksStatus(enabled: aiValue.looks != false, ready: works > 0, done: works, total: works)
    }

    /// The demo has no model: works whose words match, then the rest of
    /// the paintings, each a little less near.
    func looks(words: String) async throws -> LooksAnswer {
        try await Task.sleep(for: .milliseconds(700))
        let works = items.filter { $0.kind == .artwork }
        let matching = works.filter { Self.matches($0, PlaylistRules(query: words)) }
        return Self.answer(matching + works.filter { !matching.contains($0) }.prefix(12))
    }

    func looks(picture: Data) async throws -> LooksAnswer {
        try await Task.sleep(for: .milliseconds(900))
        return Self.answer(Array(items.filter { $0.kind == .artwork }.shuffled().prefix(18)))
    }

    func looksLike(itemID: String) async throws -> LooksAnswer {
        guard aiValue.looks != false else { return LooksAnswer(items: [], scores: []) }
        let works = items.filter { $0.kind == .artwork && $0.id != itemID }
        // The same works for the same one, as the server's numbers.
        let seed = itemID.unicodeScalars.reduce(0) { $0 &+ Int($1.value) }
        let picked = works.indices.filter { ($0 &+ seed) % 3 == 0 }.map { works[$0] }
        return Self.answer(Array(picked.prefix(10)))
    }

    private static func answer(_ found: [Item]) -> LooksAnswer {
        LooksAnswer(
            items: found.map(\.summary),
            scores: found.indices.map { 0.68 - Double($0) * 0.004 }
        )
    }

    /// The demo has no museums to ask: a pretend answer for any name.
    func museumHint(_ text: String) async throws -> MuseumHint {
        try await Task.sleep(for: .milliseconds(500))
        let words = text.trimmingCharacters(in: .whitespaces)
        guard words.count >= 3 else { return MuseumHint(total: 0, artists: [], items: []) }
        let artist = words.prefix(1).uppercased() + words.dropFirst()
        return MuseumHint(
            total: 38, artists: [TermHit(kind: "artist", key: artist, name: artist, count: 38)],
            items: remote(Array(items.shuffled().prefix(4)))
        )
    }

    func searchMuseums(_ rules: PlaylistRules, sources: [String], page: Int) async throws -> RemotePage {
        try await Task.sleep(for: .milliseconds(700))
        let found = items.filter { (sources.isEmpty || sources.contains($0.source)) && Self.matches($0, rules) }
        return RemotePage(total: page == 1 ? found.count : 0, items: page == 1 ? remote(found) : [])
    }

    /// The demo's works by museum, one museum after another.
    func museumAnswers(_ rules: PlaylistRules, sources: [String], page: Int) async throws
        -> AsyncThrowingStream<MuseumAnswer, Error>
    {
        let keys = (sources.isEmpty ? try await museums().map(\.key) : sources)
            .filter { !rules.excludeSources.contains($0) }
        let found = page == 1 ? items.filter { Self.matches($0, rules) } : []
        let answers = keys.map { key in
            let mine = found.filter { $0.source == key }
            return MuseumAnswer(source: key, total: mine.count, items: remote(mine))
        }
        return AsyncThrowingStream { continuation in
            let answering = Task {
                for answer in answers {
                    try? await Task.sleep(for: .milliseconds(350))
                    guard !Task.isCancelled else { break }
                    continuation.yield(answer)
                }
                continuation.finish()
            }
            continuation.onTermination = { _ in answering.cancel() }
        }
    }

